def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            comps.append((r1-r0+1, c1-c0+1, r0, c0, cells))
    _, _, r0, c0, cells = next(comp for comp in comps if comp[0] == comp[1])
    side = next(comp[0] for comp in comps if comp[0] == comp[1])
    cellset = set(cells)
    return [[int((r0 + r, c0 + c) in cellset) * grid[r0][c0] for c in range(side)] for r in range(side)]
